test('renderInvoiceText shows voucher line before total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const withVoucher = applyVoucher(result.value, { code: 'SAVE10', amount: 2000 });
  assert.equal(withVoucher.ok, true);

  const text = renderInvoiceText(withVoucher.value);
  const lines = text.split('\n');

  assert.match(text, /^Voucher: -€20\.00$/m);
  const voucherLineIdx = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalLineIdx = lines.findIndex(l => l.startsWith('Total:'));
  assert(voucherLineIdx < totalLineIdx);
  assert(voucherLineIdx > -1);
});

test('renderInvoiceText does not show voucher when none exists', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
  assert.ok(!text.match(/^Voucher:/m));
});

test('renderInvoiceText shows due date when present', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  assert.match(text, /^Due: 2026-11-06$/m);
});

test('renderInvoiceText does not show due date when invoice is draft', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const text = renderInvoiceText(result.value);
  assert.ok(!text.match(/^Due:/m));
});

test('renderInvoiceText shows paid amount when payments exist', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const paid = recordPayment(issued.value, { amount: 10000, date: '2026-10-09' });
  assert.equal(paid.ok, true);

  const text = renderInvoiceText(paid.value);
  assert.match(text, /^Paid: €100\.00$/m);
});

test('renderInvoiceText does not show paid line when no payments', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);

  const issued = issueInvoice(result.value, []);
  assert.equal(issued.ok, true);

  const text = renderInvoiceText(issued.value);
  assert.ok(!text.match(/^Paid:/m));
});

