import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }>, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) throw new Error('Customer not found');

  const customer = customerResult.value;
  const totals = invoiceTotals(invoice);

  const lines = [];

  lines.push(invoice.number ?? 'DRAFT');
  lines.push(customer.name);

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const qtyStr = String(line.qty);
    const nameStr = line.name;
    const unitPriceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(total);
    const discountPercent = line.discountPercent ?? 0;

    if (discountPercent > 0) {
      const discount = lineDiscount(line);
      const discountStr = formatEuros(discount);
      const netStr = formatEuros(total - discount);
      lines.push(`${qtyStr} × ${nameStr} @ ${unitPriceStr} = ${totalStr} (${discountPercent}% discount: -${discountStr}) = ${netStr}`);
    } else {
      lines.push(`${qtyStr} × ${nameStr} @ ${unitPriceStr} = ${totalStr}`);
    }
  }

  if (totals.discount > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    lines.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  if (totals.voucher > 0) {
    lines.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  if (invoice.number && invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}
